import { useForm } from 'react-hook-form';
import { zodResolver } from '@hookform/resolvers/zod';
import { z } from 'zod';

// Step 1: Define the Zod schema as the source of truth
const uploadDocumentSchema = z.object({
  title: z.string().min(3, 'Title must be at least 3 characters').max(120),
  description: z.string().optional(),
  securityGroups: z.array(z.string()).min(1, 'Select at least one access group'),
  file: z
    .instanceof(FileList)
    .refine((files) => files.length === 1, 'Please upload exactly one file')
    .refine(
      (files) => ['application/pdf', 'text/markdown'].includes(files[0].type),
      'Only PDF and Markdown files are supported'
    ),
});

// Step 2: Infer the form values type from the schema — zero duplication
type UploadDocumentValues = z.infer<typeof uploadDocumentSchema>;

export function DocumentUploadForm({ onSuccess }: { onSuccess: () => void }) {
  const {
    register,
    handleSubmit,
    setError,
    formState: { errors, isSubmitting },
  } = useForm<UploadDocumentValues>({
    resolver: zodResolver(uploadDocumentSchema),
    defaultValues: { securityGroups: [] },
  });

  const onSubmit = async (data: UploadDocumentValues) => {
    const formData = new FormData();
    formData.append('title', data.title);
    formData.append('file', data.file[0]);
    data.securityGroups.forEach((g) => formData.append('securityGroups', g));

    const res = await fetch('/api/documents', { method: 'POST', body: formData });

    if (res.status === 422) {
      const serverErrors = await res.json();
      // Map server validation errors back to individual fields
      Object.entries(serverErrors.errors).forEach(([field, message]) =>
        setError(field as keyof UploadDocumentValues, { message: message as string })
      );
      return;
    }

    if (res.ok) onSuccess();
  };

  return (
    <form onSubmit={handleSubmit(onSubmit)} className="space-y-4" noValidate>
      <div>
        <label htmlFor="title" className="block text-sm font-medium text-fg-default">Document Title</label>
        <input
          id="title"
          type="text"
          {...register('title')}
          aria-describedby={errors.title ? 'title-error' : undefined}
          aria-invalid={Boolean(errors.title)}
          className="w-full mt-1 px-3 py-2 border border-border rounded bg-canvas-default"
        />
        {errors.title && (
          <p id="title-error" role="alert" className="text-xs text-danger-fg mt-1">{errors.title.message}</p>
        )}
      </div>

      <button
        type="submit"
        disabled={isSubmitting}
        className="w-full py-2 bg-accent text-white rounded hover:bg-accent-emphasis disabled:opacity-50"
      >
        {isSubmitting ? 'Uploading...' : 'Upload Document'}
      </button>
    </form>
  );
}

import { useForm, useFieldArray } from 'react-hook-form';
import { z } from 'zod';
import { zodResolver } from '@hookform/resolvers/zod';

const schema = z.object({
  documentId: z.string(),
  tags: z.array(z.object({ value: z.string().min(1) })).min(1, 'Add at least one tag'),
});
type FormValues = z.infer<typeof schema>;

function TagsEditor({ documentId }: { documentId: string }) {
  const { control, register, formState: { errors } } = useForm<FormValues>({
    resolver: zodResolver(schema),
    defaultValues: { documentId, tags: [{ value: '' }] },
  });

  const { fields, append, remove } = useFieldArray({ control, name: 'tags' });

  return (
    <div className="space-y-2">
      {fields.map((field, index) => (
        <div key={field.id} className="flex gap-2 items-center">
          <input
            {...register(`tags.${index}.value`)}
            className="flex-1 px-2 py-1 border border-border rounded"
            placeholder="Enter tag..."
          />
          <button type="button" onClick={() => remove(index)} className="text-danger-fg">×</button>
        </div>
      ))}
      <button type="button" onClick={() => append({ value: '' })} className="text-accent-fg text-sm">
        + Add Tag
      </button>
      {errors.tags && <p className="text-xs text-danger-fg">{errors.tags.message ?? errors.tags.root?.message}</p>}
    </div>
  );
}
